import{_ as l,a0 as p,w as o,s as d,ao as h,I as t,x as i,a1 as a,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"为初学者提供的 uniq 命令教程及示例 | LCTT x X-CMD","titleTemplate":false,"description":"为初学者提供的 uniq 命令教程及示例 | LCTT (201804) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"为初学者提供的 uniq 命令教程及示例 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"为初学者提供的 uniq 命令教程及示例 | LCTT (201804) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201804/20180102 The Uniq Command Tutorial With Examples For Beginners","title":"为初学者提供的 uniq 命令教程及示例","tag":"201804","desc":""},"relativePath":"201804/20180102 The Uniq Command Tutorial With Examples For Beginners.md","filePath":"[post].md"}'),r={name:"201804/20180102 The Uniq Command Tutorial With Examples For Beginners.md"};function c(g,s,u,k,b,x){const e=p("Link");return o(),d("div",null,[s[13]||(s[13]=h(`<h1 id="为初学者提供的-uniq-命令教程及示例" tabindex="-1">为初学者提供的 uniq 命令教程及示例 <a class="header-anchor" href="#为初学者提供的-uniq-命令教程及示例" aria-label="Permalink to “为初学者提供的 uniq 命令教程及示例”">​</a></h1><p>如果你主要是在命令行上工作，并且每天处理大量的文本文件，那么你应该了解下 <code>uniq</code> 命令。该命令会帮助你轻松地从文件中找到重复的行。它不仅用于查找重复项，而且我们还可以使用它来删除重复项，显示重复项的出现次数，只显示重复的行，只显示唯一的行等。由于 <code>uniq</code> 命令是 GNU coreutils 包的一部分，所以它预装在大多数 Linux 发行版中，让我们不需要费心安装。来看一些实际的例子。</p><p>请注意，除非重复行是相邻的，否则 <code>uniq</code> 不会删除它们。因此，你可能需要先对它们进行排序，或将排序命令与 <code>uniq</code> 组合以获得结果。让我给你看一些例子。</p><p>首先，让我们创建一个带有一些重复行的文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>vi ostechnix.txt</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>welcome to ostechnix</span></span>
<span class="line"><span>welcome to ostechnix</span></span>
<span class="line"><span>Linus is the creator of Linux.</span></span>
<span class="line"><span>Linux is secure by default</span></span>
<span class="line"><span>Linus is the creator of Linux.</span></span>
<span class="line"><span>Top 500 super computers are powered by Linux</span></span></code></pre></div><p>正如你在上面的文件中看到的，我们有一些重复的行（第一行和第二行，第三行和第五行是重复的）。</p><h3 id="_1、-使用-uniq-命令删除文件中的连续重复行" tabindex="-1">1、 使用 uniq 命令删除文件中的连续重复行 <a class="header-anchor" href="#_1、-使用-uniq-命令删除文件中的连续重复行" aria-label="Permalink to “1、 使用 uniq 命令删除文件中的连续重复行”">​</a></h3><p>如果你在不使用任何参数的情况下使用 <code>uniq</code> 命令，它将删除所有连续的重复行，只显示唯一的行。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>uniq ostechnix.txt</span></span></code></pre></div><p>示例输出：</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/01/uniq-2.png" alt=""></p><p>如你所见， <code>uniq</code> 命令删除了给定文件中的所有连续重复行。你可能还注意到，上面的输出仍然有第二行和第四行重复了。这是因为 <code>uniq</code> 命令只有在相邻的情况下才会删除重复的行，当然，我们也可以删除非连续的重复行。请看下面的第二个例子。</p><h3 id="_2、-删除所有重复的行" tabindex="-1">2、 删除所有重复的行 <a class="header-anchor" href="#_2、-删除所有重复的行" aria-label="Permalink to “2、 删除所有重复的行”">​</a></h3><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sort ostechnix.txt | uniq</span></span></code></pre></div><p>示例输出：</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/01/uniq-1-1.png" alt=""></p><p>看到了吗？没有重复的行。换句话说，上面的命令将显示在 <code>ostechnix.txt</code> 中只出现一次的行。我们使用 <code>sort</code> 命令与 <code>uniq</code> 命令结合，因为，就像我提到的，除非重复行是相邻的，否则 <code>uniq</code> 不会删除它们。</p><h3 id="_3、-只显示文件中唯一的一行" tabindex="-1">3、 只显示文件中唯一的一行 <a class="header-anchor" href="#_3、-只显示文件中唯一的一行" aria-label="Permalink to “3、 只显示文件中唯一的一行”">​</a></h3><p>为了只显示文件中唯一的一行，可以这样做：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sort ostechnix.txt | uniq -u</span></span></code></pre></div><p>示例输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Linux is secure by default</span></span>
<span class="line"><span>Top 500 super computers are powered by Linux</span></span></code></pre></div><p>如你所见，在给定的文件中只有两行是唯一的。</p><h3 id="_4、-只显示重复的行" tabindex="-1">4、 只显示重复的行 <a class="header-anchor" href="#_4、-只显示重复的行" aria-label="Permalink to “4、 只显示重复的行”">​</a></h3><p>同样的，我们也可以显示文件中重复的行，就像下面这样：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sort ostechnix.txt | uniq -d</span></span></code></pre></div><p>示例输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Linus is the creator of Linux.</span></span>
<span class="line"><span>welcome to ostechnix</span></span></code></pre></div><p>这两行在 <code>ostechnix.txt</code> 文件中是重复的行。请注意 <code>-d</code>（小写 <code>d</code>） 将会只打印重复的行，每组显示一个。打印所有重复的行，使用 <code>-D</code>（大写 <code>D</code>），如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sort ostechnix.txt | uniq -D</span></span></code></pre></div><p>在下面的截图中看两个选项的区别：</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/01/uniq-4.png" alt=""></p><h3 id="_5、-显示文件中每一行的出现次数" tabindex="-1">5、 显示文件中每一行的出现次数 <a class="header-anchor" href="#_5、-显示文件中每一行的出现次数" aria-label="Permalink to “5、 显示文件中每一行的出现次数”">​</a></h3><p>由于某种原因，你可能想要检查给定文件中每一行重复出现的次数。要做到这一点，使用 <code>-c</code> 选项，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sort ostechnix.txt | uniq -c</span></span></code></pre></div><p>示例输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span> 2 Linus is the creator of Linux.</span></span>
<span class="line"><span> 1 Linux is secure by default</span></span>
<span class="line"><span> 1 Top 500 super computers are powered by Linux</span></span>
<span class="line"><span> 2 welcome to ostechnix</span></span></code></pre></div><p>我们还可以按照每一行的出现次数进行排序，然后显示，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sort ostechnix.txt | uniq -c | sort -nr</span></span></code></pre></div><p>示例输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span> 2 welcome to ostechnix</span></span>
<span class="line"><span> 2 Linus is the creator of Linux.</span></span>
<span class="line"><span> 1 Top 500 super computers are powered by Linux</span></span>
<span class="line"><span> 1 Linux is secure by default</span></span></code></pre></div><h3 id="_6、-将比较限制为-n-个字符" tabindex="-1">6、 将比较限制为 N 个字符 <a class="header-anchor" href="#_6、-将比较限制为-n-个字符" aria-label="Permalink to “6、 将比较限制为 N 个字符”">​</a></h3><p>我们可以使用 <code>-w</code> 选项来限制对文件中特定数量字符的比较。例如，让我们比较文件中的前四个字符，并显示重复行，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>uniq -d -w 4 ostechnix.txt</span></span></code></pre></div><h3 id="_7、-忽略比较指定的-n-个字符" tabindex="-1">7、 忽略比较指定的 N 个字符 <a class="header-anchor" href="#_7、-忽略比较指定的-n-个字符" aria-label="Permalink to “7、 忽略比较指定的 N 个字符”">​</a></h3><p>像对文件中行的前 N 个字符进行限制比较一样，我们也可以使用 <code>-s</code> 选项来忽略比较前 N 个字符。</p><p>下面的命令将忽略在文件中每行的前四个字符进行比较：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>uniq -d -s 4 ostechnix.txt</span></span></code></pre></div><p>为了忽略比较前 N 个字段（LCTT 译注：即前几列）而不是字符，在上面的命令中使用 <code>-f</code> 选项。</p><p>欲了解更多详情，请参考帮助部分：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>uniq --help</span></span></code></pre></div><p>也可以使用 <code>man</code> 命令查看：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>man uniq</span></span></code></pre></div><p>今天就到这里！我希望你现在对 <code>uniq</code> 命令及其目的有一个基本的了解。如果你发现我们的指南有用，请在你的社交网络上分享，并继续支持我们。更多好东西要来了，请继续关注！</p><p>干杯！</p><hr>`,57)),t("p",null,[s[1]||(s[1]=i("via: ",-1)),a(e,{href:"https://www.ostechnix.com/uniq-command-tutorial-examples-beginners/"},{default:n(()=>[...s[0]||(s[0]=[i("https://www.ostechnix.com/uniq-command-tutorial-examples-beginners/",-1)])]),_:1})]),t("p",null,[s[5]||(s[5]=i("作者：",-1)),a(e,{href:"https://www.ostechnix.com"},{default:n(()=>[...s[2]||(s[2]=[i("SK",-1)])]),_:1}),s[6]||(s[6]=i(" 译者：",-1)),a(e,{href:"https://github.com/MjSeven"},{default:n(()=>[...s[3]||(s[3]=[i("MjSeven",-1)])]),_:1}),s[7]||(s[7]=i(" 校对：",-1)),a(e,{href:"https://github.com/wxy"},{default:n(()=>[...s[4]||(s[4]=[i("wxy",-1)])]),_:1})]),t("p",null,[s[10]||(s[10]=i("本文由 ",-1)),a(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[8]||(s[8]=[i("LCTT",-1)])]),_:1}),s[11]||(s[11]=i(" 原创编译，",-1)),a(e,{href:"https://linux.cn/"},{default:n(()=>[...s[9]||(s[9]=[i("Linux中国",-1)])]),_:1}),s[12]||(s[12]=i(" 荣誉推出",-1))])])}const C=l(r,[["render",c]]);export{y as __pageData,C as default};
